import { test, expect } from '@playwright/test';

test.describe('User Profile Data Export', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
    await page.getByRole('button', { name: 'Login' }).click();
    await page.getByLabel('Username').fill('testuser');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Submit' }).click();
  });

  test('should display export data button', async ({ page }) => {
    const exportButton = page.getByRole('button', { name: 'Export Data' });
    await expect(exportButton).toBeVisible();
  });

  test('should export personal data as JSON file', async ({ page }) => {
    await page.getByRole('button', { name: 'Export Data' }).click();
    const [download] = await Promise.all([
      page.waitForEvent('download'),
      page.getByRole('button', { name: 'Export Data' }).click(),
    ]);
    const path = await download.path();
    expect(path).toBeTruthy();
    expect(path.endsWith('.json')).toBe(true);
  });
});
